  Definition keptA (R R' : bvmap 5 word) : Prop := kept R R' /\ getr R' 10%bv = getr R 10%bv.
  Lemma keptA_trans : forall R1 R2 R3, keptA R1 R2 -> keptA R2 R3 -> keptA R1 R3.
Proof using.
