  Lemma head_loop : forall k R i,
    i = n - 1 - Z.of_nat k -> 0 <= i ->
    getr R 11%bv = Z_to_bv 64 (p + i) -> getr R 12%bv = Z_to_bv 64 (p + i + 1) ->
    exists R', keptA R R' /\
      ( (exists q, q mod 8 = 0 /\ p <= q <= p + n /\ msteps SEGS (st R SL_HEAD) (st R' SL_ALGN) /\ getr R' 12%bv = Z_to_bv 64 q)
